sys_script.script:
(function executeRule(current, previous /*null when async*/) {

// 1. Prevent users from setting an expiration date in the past

var expDateStr = current.getValue('u_expiration_date');
if (expDateStr){
	var expDate = new GlideDateTime(expDateStr);
	var today = new GlideDateTime();

	// Strip the time to compare just the calendar dates (optional, ensures today's date passes)
	expDate.setDisplayValue(expDate.getLocalDate().getDisplayValue()+ " 00:00:00");
	today.setDisplayValue(today.getLocalDate().getDisplayValue() + " 00:00:00");

	if(expDate.before(today)){
		gs.addErrorMessage('The Expiration Date cannot be set in the past.');
		current.setAbortAction(true);
		return; // Stop further execution of this rule
	}
}

 // 2. Check: If Request type is New High-End and no Business justification was entered
// Replace 'u_request_type', 'new_high_end', and 'u_business_justification' with your actual field/choice names

if(current.getValue('u_request_type') == 'new_high-end' && current.description.nil()){
	gs.addErrorMessage('A Business Justification is required for New High-End requests.');
	current.setAbortAction(true);
}

})(current, previous);
